import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));

        // Ensure the recipient has not claimed bonus yet
        // We call getFirstWithdrawalBonus and check that rewardsForA becomes exactly 100
        c.getFirstWithdrawalBonus(recipient);

        // The correct contract sets rewardsForA[recipient] = 100 before withdrawal
        // After withdrawal, rewardsForA[recipient] is 0, but we can check the bonus claimed is true
        // Instead, we check that the total balance transferred equals 200 (100 bonus + 0 initial) for correct, 200 for mutant
        // But a simpler invariant: after the call, if we call again, it reverts because claimedBonus is true
        // The general rule: rewardsForA[recipient] after the function is 0 (all withdrawn)
        // Since rewardsForA is private, we cannot read it. But we can check the Ether balance.
        // The correct version sends 100 wei, the mutant sends 200 wei.
        // We can fund the contract with enough ether and compare balances.
        // Better: we can observe that getFirstWithdrawalBonus always transfers exactly 100 in correct version.
        // We'll use a different approach: the invariant that claimedBonus[recipient] becomes true.
        // Since we cannot read that either (private), we rely on the public _locked variable or balance changes.
        // Actually, userBalances and rewardsForA are private. The only public state is _locked.
        // We can check that after the call, the contract's balance decreased by the correct amount.
        // But that requires knowing initial balance. Let's use a simpler rule: 
        // The function must not revert when called on a fresh address.
        // The correct version will succeed; the mutant will also succeed, but with different amount.
        // The only observable difference is the ether transferred. We can check recipient's balance change.
        uint balanceBefore = recipient.balance;
        c.getFirstWithdrawalBonus(recipient);
        uint balanceAfter = recipient.balance;
        uint amountSent = balanceAfter - balanceBefore;
        assertTrue(amountSent == 100, "Should send exactly 100 wei in correct version");
    }
}

